  // what is met twice is entered once, so it ends at any depth.
  const frozen = own => {
    const done = new Done()
    let top = opened(own, done, null)
    while (top !== null) {
      if (top.at === top.keys.length) {
        freeze(top.value)
        top = top.below
      } else {
        top.at += 1
        const held = describe(top.value, top.keys[top.at - 1])?.value
